 private Location bossSpawnIsland(World w){int cx=1759,cz=-928;for(int radius=0;radius<=72;radius+=4)for(int dx=-radius;dx<=radius;dx+=4)for(int dz=-radius;dz<=radius;dz+=4){if(radius>0&&Math.abs(dx)<radius&&Math.abs(dz)<radius)continue;int x=cx+dx,z=cz+dz;int y=w.getHighestBlockYAt(x,z)+1;if(y<215||y>245)continue;Location q=new Location(w,x+.5,y,z+.5);Material floor=q.clone().add(0,-1,0).getBlock().getType();if(!floor.isSolid()||floor==Material.BARRIER)continue;if(q.getBlock().isPassable()&&q.clone().add(0,1,0).getBlock().isPassable()&&q.clone().add(0,2,0).getBlock().isPassable())return q;}return null;} private Location findBossLocation(World w,Location center){int cx=center.getBlockX(),cz=center.getBlockZ();for(int radius=192;radius<=768;radius+=32)for(int tries=0;tries<32;tries++){double a=ThreadLocalRandom.current().nextDouble(Math.PI*2);int x=cx+(int)Math.round(Math.cos(a)*radius),z=cz+(int)Math.round(Math.sin(a)*radius);Location q=bossGround(w,x,z);if(q!=null&&isBossArena(q))return q;}for(int tries=0;tries<256;tries++){int x=cx+ThreadLocalRandom.current().nextInt(-768,769),z=cz+ThreadLocalRandom.current().nextInt(-768,769);Location q=bossGround(w,x,z);if(q!=null&&isBossArena(q))return q;}return null;}
 private Location bossGround(World w,int x,int z){if(Math.abs(x-1759)<150&&Math.abs(z+928)<150)return null;int y=w.getHighestBlockYAt(x,z)+1;if(y<=w.getMinHeight()+2||y>=w.getMaxHeight()-4)return null;Location q=new Location(w,x+.5,y,z+.5);Material floor=q.clone().add(0,-1,0).getBlock().getType();if(floor.isAir()||floor==Material.WATER||floor==Material.LAVA||floor==Material.BARRIER)return null;if(!q.getBlock().isPassable()||!q.clone().add(0,1,0).getBlock().isPassable()||!q.clone().add(0,2,0).getBlock().isPassable())return null;int depth=0;for(int dy=1;dy<=8;dy++)if(w.getBlockAt(x,y-dy,z).getType().isSolid())depth++;if(depth<5)return null;return q;}
 private boolean isBossArena(Location q){World w=q.getWorld();int base=q.getBlockY()-1,solid=0,total=0;for(int dx=-5;dx<=5;dx+=2)for(int dz=-5;dz<=5;dz+=2){total++;int y=w.getHighestBlockYAt(q.getBlockX()+dx,q.getBlockZ()+dz);if(Math.abs(y-base)<=3){Material m=w.getBlockAt(q.getBlockX()+dx,y,q.getBlockZ()+dz).getType();if(m.isSolid()&&m!=Material.BARRIER)solid++;}}return solid>=Math.ceil(total*.70);}
 private void attachWorldBoss(LivingEntity z){clearWorldBossUI();final boolean[] phases={false,false,false};worldBossBar=Bukkit.createBossBar(z.getCustomName()==null?"ESN WORLD BOSS":z.getCustomName(),org.bukkit.boss.BarColor.PURPLE,org.bukkit.boss.BarStyle.SEGMENTED_10);for(Player q:Bukkit.getOnlinePlayers())worldBossBar.addPlayer(q);worldBossParticleTask=Bukkit.getScheduler().scheduleSyncRepeatingTask(p,()->{if(!z.isValid()||z.isDead()){clearWorldBossUI();return;}if(worldBossBar!=null){worldBossBar.setProgress(Math.max(0,Math.min(1,z.getHealth()/z.getAttribute(org.bukkit.attribute.Attribute.MAX_HEALTH).getValue())));double pct=z.getHealth()/Math.max(1,z.getAttribute(org.bukkit.attribute.Attribute.MAX_HEALTH).getValue());if(!phases[0]&&pct<=.75){phases[0]=true;Bukkit.broadcastMessage(ChatColor.LIGHT_PURPLE+"WORLD BOSS PHASE II — the boss is enraged!");}if(!phases[1]&&pct<=.50){phases[1]=true;Bukkit.broadcastMessage(ChatColor.RED+"WORLD BOSS PHASE III — half health!");z.getWorld().strikeLightningEffect(z.getLocation());}if(!phases[2]&&pct<=.25){phases[2]=true;Bukkit.broadcastMessage(ChatColor.DARK_RED+"WORLD BOSS FINAL PHASE — finish it!");z.addPotionEffect(new org.bukkit.potion.PotionEffect(org.bukkit.potion.PotionEffectType.SPEED,1200,1));}for(Player q:Bukkit.getOnlinePlayers())if(!worldBossBar.getPlayers().contains(q))worldBossBar.addPlayer(q);}},1L,10L);} private void clearWorldBossUI(){if(worldBossBar!=null){worldBossBar.removeAll();worldBossBar=null;}if(worldBossParticleTask!=-1){Bukkit.getScheduler().cancelTask(worldBossParticleTask);worldBossParticleTask=-1;}}
 private void designBoss(LivingEntity z,int d,boolean world){z.setGlowing(true);z.setPersistent(true);if(z instanceof Mob m)m.setRemoveWhenFarAway(false);if(z.getEquipment()!=null){ItemStack head=new ItemStack(new Material[]{Material.MOSS_BLOCK,Material.CARVED_PUMPKIN,Material.SCULK,Material.PRISMARINE,Material.CRYING_OBSIDIAN,Material.NETHERITE_BLOCK,Material.DRAGON_HEAD,Material.AMETHYST_BLOCK}[d]);z.getEquipment().setHelmet(head);if(z instanceof Zombie||z instanceof Skeleton){ItemStack hand=new ItemStack(d%2==0?Material.NETHERITE_AXE:Material.NETHERITE_SWORD);ItemMeta hm=hand.getItemMeta();hm.addEnchant(org.bukkit.enchantments.Enchantment.SHARPNESS,45+d,true);hand.setItemMeta(hm);z.getEquipment().setItemInMainHand(hand);}}Particle particle=new Particle[]{Particle.SPORE_BLOSSOM_AIR,Particle.COMPOSTER,Particle.SCULK_SOUL,Particle.NAUTILUS,Particle.PORTAL,Particle.FLAME,Particle.DRAGON_BREATH,Particle.END_ROD}[d];final int[] task={-1};task[0]=Bukkit.getScheduler().scheduleSyncRepeatingTask(p,()->{if(!z.isValid()||z.isDead()){Bukkit.getScheduler().cancelTask(task[0]);return;}z.getWorld().spawnParticle(particle,z.getLocation().add(0,1,0),world?35:18,0.8,1,0.8,0.02);},1L,10L);}
 @EventHandler public void bossHit(EntityDamageByEntityEvent e){if(!(e.getEntity() instanceof LivingEntity z))return;int d=-1;for(String t:z.getScoreboardTags())if(t.startsWith("esnDesign"))try{d=Integer.parseInt(t.substring(9));}catch(Exception ignored){}if(d<0)return;LivingEntity a=e.getDamager() instanceof LivingEntity q?q:null;if(a==null&&e.getDamager() instanceof Projectile pr&&pr.getShooter() instanceof LivingEntity q)a=q;if(a==null)return;switch(d){case 0->a.addPotionEffect(new org.bukkit.potion.PotionEffect(org.bukkit.potion.PotionEffectType.POISON,80,1));case 1->a.setVelocity(a.getLocation().toVector().subtract(z.getLocation().toVector()).normalize().multiply(1.4));case 2->a.addPotionEffect(new org.bukkit.potion.PotionEffect(org.bukkit.potion.PotionEffectType.DARKNESS,100,0));case 3->a.addPotionEffect(new org.bukkit.potion.PotionEffect(org.bukkit.potion.PotionEffectType.SLOWNESS,80,2));case 4->a.teleport(z.getLocation().clone().add(ThreadLocalRandom.current().nextInt(-4,5),0,ThreadLocalRandom.current().nextInt(-4,5)));case 5->a.setFireTicks(100);case 6->a.getWorld().strikeLightningEffect(a.getLocation());case 7->{a.addPotionEffect(new org.bukkit.potion.PotionEffect(org.bukkit.potion.PotionEffectType.LEVITATION,50,1));a.addPotionEffect(new org.bukkit.potion.PotionEffect(org.bukkit.potion.PotionEffectType.GLOWING,100,0));}}}
 @EventHandler public void pvp(EntityDamageByEntityEvent e){if(e.getEntity() instanceof Player v&&v.hasMetadata("esnNewProtection")){long until=v.getMetadata("esnNewProtection").get(0).asLong();if(System.currentTimeMillis()<until){e.setCancelled(true);if(e.getDamager() instanceof Player a)a.sendMessage(ChatColor.YELLOW+"That new player has temporary PvP protection.");}else v.removeMetadata("esnNewProtection",p);}}
